import React from 'react';
import { Group, Button, IconButton, Chip } from '@salutejs/sdds-finai';
import { IconClose } from '@salutejs/plasma-icons';
export function App() {
    return (
        <div>
            <Group shape="segmented">
                <Button text="Button" />
                <IconButton>
                    <IconClose color="inherit" />
                </IconButton>
                <Chip text="Chip" hasClear={false} />
            </Group>
            <Group shape="segmented" orientation="vertical" gap="wide">
                <Button text="Button" />
                <IconButton>
                    <IconClose color="inherit" />
                </IconButton>
                <Chip text="Chip" hasClear={false} />
            </Group>
        </div>
    );
}
